1. using Microsoft.ML;
2. using Microsoft.ML.Data;
3. using Microsoft.Extensions.ML;
4. 
5. var builder = WebApplication.CreateBuilder(args);
6. 
7. // Train the model at startup and register pooled prediction engine
8. var mlContext = new MLContext(seed: 42);
9. var dataPath = Path.Combine(AppContext.BaseDirectory, "Data", "customers.csv");
10. var allData = mlContext.Data.LoadFromTextFile<CustomerData>(dataPath, hasHeader: true, separatorChar: ',');
11. 
12. // Map "Yes"/"No" string to boolean Label column
13. var labelMapping = new Dictionary<string, bool> { ["Yes"] = true, ["No"] = false };
14. var pipeline = mlContext.Transforms.Conversion.MapValue("Label", labelMapping.AsEnumerable(),
15.         inputColumnName: nameof(CustomerData.Churned))
16.     .Append(mlContext.Transforms.Categorical.OneHotEncoding("RegionEncoded", nameof(CustomerData.Region)))
17.     .Append(mlContext.Transforms.Concatenate("Features", nameof(CustomerData.Age), nameof(CustomerData.Income),
18.         "RegionEncoded", nameof(CustomerData.PurchaseHistory)))
19.     .Append(mlContext.Transforms.NormalizeMinMax("Features"))
20.     .Append(mlContext.BinaryClassification.Trainers.SdcaLogisticRegression(
21.         labelColumnName: "Label", featureColumnName: "Features"));
22. 
23. // With a larger dataset, use TrainTestSplit and evaluate on held-out data:
24. //   var split = mlContext.Data.TrainTestSplit(allData, testFraction: 0.2, seed: 42);
25. //   var model = pipeline.Fit(split.TrainSet);
26. //   var metrics = mlContext.BinaryClassification.Evaluate(model.Transform(split.TestSet));
27. var model = pipeline.Fit(allData);
28. 
29. var predictions = model.Transform(allData);
30. var metrics = mlContext.BinaryClassification.Evaluate(predictions, labelColumnName: "Label");
31. Console.WriteLine($"Model trained — AUC: {metrics.AreaUnderRocCurve:F4}, Accuracy: {metrics.Accuracy:F4}, F1: {metrics.F1Score:F4}");
32. 
33. var modelPath = Path.Combine(AppContext.BaseDirectory, "churn-model.zip");
34. mlContext.Model.Save(model, allData.Schema, modelPath);
35. 
36. builder.Services.AddPredictionEnginePool<CustomerData, ChurnPrediction>()
37.     .FromFile(modelPath);
38. 
39. var app = builder.Build();
40. 
41. app.MapPost("/predict", (PredictionEnginePool<CustomerData, ChurnPrediction> pool, CustomerRequest req) =>
42. {
43.     var input = new CustomerData
44.     {
45.         Age = req.Age,
46.         Income = req.Income,
47.         Region = req.Region,
48.         PurchaseHistory = req.PurchaseHistory
49.     };
50.     var prediction = pool.Predict(input);
51.     return Results.Ok(new
52.     {
53.         WillChurn = prediction.PredictedLabel,
54.         Confidence = prediction.Probability
55.     });
56. });
57. 
58. app.Run();
59. 
