 // Train the model at startup and register pooled prediction engine
 var mlContext = new MLContext(seed: 42);
 var dataPath = Path.Combine(AppContext.BaseDirectory, "Data", "customers.csv");
 var allData = mlContext.Data.LoadFromTextFile<CustomerData>(dataPath, hasHeader: true, separatorChar: ',');

 // Map "Yes"/"No" string to boolean Label column
 var labelMapping = new Dictionary<string, bool> { ["Yes"] = true, ["No"] = false };
 var pipeline = mlContext.Transforms.Conversion.MapValue("Label", labelMapping.AsEnumerable(),
         inputColumnName: nameof(CustomerData.Churned))
     .Append(mlContext.Transforms.Categorical.OneHotEncoding("RegionEncoded", nameof(CustomerData.Region)))
     .Append(mlContext.Transforms.Concatenate("Features", nameof(CustomerData.Age), nameof(CustomerData.Income),
         "RegionEncoded", nameof(CustomerData.PurchaseHistory)))
     .Append(mlContext.Transforms.NormalizeMinMax("Features"))
     .Append(mlContext.BinaryClassification.Trainers.SdcaLogisticRegression(
         labelColumnName: "Label", featureColumnName: "Features"));

 // With a larger dataset, use TrainTestSplit and evaluate on held-out data:
 //   var split = mlContext.Data.TrainTestSplit(allData, testFraction: 0.2, seed: 42);
 //   var model = pipeline.Fit(split.TrainSet);
 //   var metrics = mlContext.BinaryClassification.Evaluate(model.Transform(split.TestSet));
 var model = pipeline.Fit(allData);

 var predictions = model.Transform(allData);
 var metrics = mlContext.BinaryClassification.Evaluate(predictions, labelColumnName: "Label");
 Console.WriteLine($"Model trained — AUC: {metrics.AreaUnderRocCurve:F4}, Accuracy: {metrics.Accuracy:F4}, F1: {metrics.F1Score:F4}");

 var modelPath = Path.Combine(AppContext.BaseDirectory, "churn-model.zip");
 mlContext.Model.Save(model, allData.Schema, modelPath);

 builder.Services.AddPredictionEnginePool<CustomerData, ChurnPrediction>()
     .FromFile(modelPath);

 var app = builder.Build();

 app.MapPost("/predict", (PredictionEnginePool<CustomerData, ChurnPrediction> pool, CustomerRequest req) =>
 {
     var input = new CustomerData
     {
         Age = req.Age,
         Income = req.Income,
         Region = req.Region,
         PurchaseHistory = req.PurchaseHistory
     };
     var prediction = pool.Predict(input);
     return Results.Ok(new
     {
         WillChurn = prediction.PredictedLabel,
         Confidence = prediction.Probability
     });
 });

 app.Run();

 // ML.NET data models
 public class CustomerData
 {
     [LoadColumn(0)] public float Age { get; set; }
     [LoadColumn(1)] public float Income { get; set; }
     [LoadColumn(2)] public string Region { get; set; } = string.Empty;
     [LoadColumn(3)] public float PurchaseHistory { get; set; }
     [LoadColumn(4)] public string Churned { get; set; } = string.Empty;
 }

 public class ChurnPrediction
 {
     [ColumnName("PredictedLabel")] public bool PredictedLabel { get; set; }
     public float Probability { get; set; }
     public float Score { get; set; }
 }

 public record CustomerRequest(float Age, float Income, string Region, float PurchaseHistory);

